namespace DriveOS.Modules.CurriculumPedagogy.Infrastructure;
public static class DependencyInjection{public static IServiceCollection AddCurriculumPedagogyInfrastructure(this IServiceCollection s,IConfiguration c){var cs=c.GetConnectionString("DriveOS")??throw new InvalidOperationException("The DriveOS database connection string is missing.");s.AddScoped<CurriculumPedagogyAuditInterceptor>();s.AddDbContext<CurriculumPedagogyDbContext>((sp,o)=>{o.UseNpgsql(cs,n=>n.MigrationsHistoryTable("__ef_migrations_history",CurriculumPedagogySchema.Name));o.AddInterceptors(sp.GetRequiredService<CurriculumPedagogyAuditInterceptor>());});s.AddScoped<ICurriculumPedagogyUnitOfWork>(sp=>sp.GetRequiredService<CurriculumPedagogyDbContext>());s.AddScoped<ICurriculumRepository,CurriculumRepository>();s.AddScoped<ILicenseCategoryDefinitionRepository,LicenseCategoryDefinitionRepository>();s.AddScoped<ICurriculumReadService,CurriculumReadService>();s.AddScoped<ITrainingPathRepository,TrainingPathRepository>();s.AddScoped<ICurriculumVersionEligibilityService,CurriculumVersionEligibilityService>();s.AddScoped<ITrainingPathReadService,TrainingPathReadService>();s.AddScoped<ICompetencyRecordRepository,CompetencyRecordRepository>();s.AddScoped<ICurriculumCompetencyEligibilityService,CurriculumCompetencyEligibilityService>();s.AddScoped<ICompetencyRecordReadService,CompetencyRecordReadService>();s.AddScoped<IPedagogicalProgressionReadService,PedagogicalProgressionReadService>();s.AddScoped<IPedagogicalReviewRepository,PedagogicalReviewRepository>();s.AddScoped<IPedagogicalReviewReadService,PedagogicalReviewReadService>();s.AddScoped<IRemediationPlanRepository,RemediationPlanRepository>();s.AddScoped<IRemediationPlanReadService,RemediationPlanReadService>();s.AddScoped<IPedagogicalReadinessDecisionRepository,PedagogicalReadinessDecisionRepository>();s.AddScoped<IPedagogicalReadinessReadService,PedagogicalReadinessReadService>();s.AddScoped<IStudentPedagogyOverviewReadService,StudentPedagogyOverviewReadService>();return s;}}
